USE CustDB
GO

CREATE TABLE #tmpSMA (custid INT PRIMARY KEY, ModifiedDate DATETIME)

CREATE TABLE #tmpSMA_CTS (custid INT PRIMARY KEY, oldModifiedDate DATETIME, IsFinished BIT DEFAULT (0))


;WITH CTE_CustCategoryHistory AS (
	SELECT DISTINCT custid
	FROM CustCategoryHistory WITH (NOLOCK)
	WHERE CreatedDate BETWEEN '2024-11-19 00:00:00' AND '2024-11-19 23:02:51.19'
	AND CustomerClass IN (30000,31000)

)
INSERT INTO #tmpSMA (custid, ModifiedDate)
SELECT pa.custid, pa.ModifiedDate
FROM CTE_CustCategoryHistory his
INNER JOIN ProblemAccountClassification pa WITH(NOLOCK) ON his.custid=pa.custid
INNER JOIN Customer c WITH (NOLOCK) ON c.custid=his.custid
WHERE c.roleid BETWEEN 2 AND 4
AND pa.ModifiedDate BETWEEN '2024-11-19 00:00:00' AND '2024-11-19 23:02:51.19'


