DECLARE @Cust_cnt INT

SELECT @Cust_cnt = COUNT(1)
FROM #tmpSMA T

DECLARE @msg_total NVARCHAR(200) = 'Total of Customers Affected: %d.'

RAISERROR (@msg_total, 0, 1, @Cust_cnt) WITH NOWAIT


-- Revert ModifiedDate
WHILE EXISTS (SELECT TOP 1 1 FROM #tmpSMA_CTS WHERE IsFinished=0)
BEGIN
	UPDATE TOP (3000) #tmpSMA_CTS
	SET IsFinished=1
	WHERE IsFinished=0

	IF @@ROWCOUNT=0
		BREAK

	UPDATE pa WITH (ROWLOCK, UPDLOCK)
	SET pa.ModifiedDate=old.oldModifiedDate
	FROM ProblemAccountClassification pa
	INNER JOIN #tmpSMA t ON t.custid=pa.custid
	INNER JOIN #tmpSMA_CTS old ON old.custid=pa.custid
	WHERE old.IsFinished=1

	DELETE T
	FROM #tmpSMA T
	INNER JOIN #tmpSMA_CTS old ON old.custid=t.custid
	WHERE old.IsFinished=1

	WAITFOR DELAY '00:00:050'
END
GO